def statement(request):
    """Show the credit assigned to every line of one complete monthly statement.

    Lines keep their input order. Overall amounts equal total() for the same input.
    """
    release = resolve_release(request)
    if release is None:
        return {"error": "unsupported_release"}
    lines = request["lines"]
    credits = assign_credits(lines, release)
    response_lines = [
        {
            "line_id": line["line_id"],
            "credit_cents": credits[line["line_id"]],
            "amount_due_cents": line["charge_cents"] - credits[line["line_id"]],
        }
        for line in lines
    ]
    credit = sum(credits.values())
    charges = sum(line["charge_cents"] for line in lines)
    return {
        "release": release,
        "lines": response_lines,
        "credit_cents": credit,
        "amount_due_cents": charges - credit,
    }


def handle(request):
    command = request.get("command")
    if command == "ping":
        return {"status": "ok", "product": PRODUCT}
    if command == "quote":
        return quote(request)
    if command == "total":
        return total(request)
    if command == "statement":
        return statement(request)
    return {"error": "unknown_command"}
